input.command:
cd /work/workspace && python3 - <<'EOF'
import re, json, pathlib

# 1) filenames cited in deliverables vs real library files
lib_files = {p.name for p in pathlib.Path('library').glob('*.md')}
cited = set()
for p in pathlib.Path('deliverable').glob('*.md'):
    cited |= set(re.findall(r'`([a-z0-9_]+\.md)`', p.read_text(encoding='utf-8')))
deliverable_self = {p.name for p in pathlib.Path('deliverable').glob('*.md')}
phantom = {c for c in cited if c not in lib_files and c not in deliverable_self}
print("citados:", sorted(cited))
print("FANTASMAS:", sorted(phantom) or "nenhum")

# 2) numeros.json still parses and schema keys
d = json.load(open('deliverable/numeros.json', encoding='utf-8'))
expected = {"itbi","simples_possivel","pro_labore_minimo_recomendado_mensal","distribuicao_mensal_pretendida","irrf_dividendos_2026_estimado_mensal","integralizacao_imovel"}
print("schema keys ok:", set(d.keys()) == expected)

# 3) version-header sweep
for p in sorted(pathlib.Path('deliverable').glob('*.md')):
    first = p.read_text(encoding='utf-8').splitlines()[0]
    print(p.name, "->", first[:90])
EOF

